ee:variables.ee:set-variable:
%dw 2.0
import epochMs, nowIso from modules::util
output application/java
var period = (now() >> "UTC") as String {format: "yyyy-MM"}
var monthStart = (period ++ "-01T00:00:00Z") as DateTime
var prevStart = monthStart - |P1M|
---
{
	period: period,
	at: nowIso(),
	// Usage data lags ~3 days, so the previous month is re-read every run until it is final.
	// One query per month keeps each window inside the API's 60-day limit.
	months: [
		{ period: prevStart as String {format: "yyyy-MM"}, fromMs: epochMs(prevStart), toMs: epochMs(monthStart) - 1 },
		{ period: period, fromMs: epochMs(monthStart), toMs: epochMs(now()) }
	]
}
